save(81,dict(paragraphs=["Lipsa Patel’s Odia contributions to Kabita Live move between inward endurance and the pressures of everyday life. ‘ଚିରସାଥୀ’ asks whether every sorrow can be shared, then imagines pain as a sign of continuing life. Its winding river and difficult arithmetic suggest that living is an ongoing search for a way through.","In ‘ଧୂଆଁ’, smoke becomes an image of damaged trust and a past that continues to trouble the present. ‘କରୋନା ଭଲ ଥିଲା’ uses an ironic refrain to question the expense, pollution and social demands surrounding festivals. The contrast between celebration and a household’s strain gives the poem its sharp, unsettling force."],sources=[],status='source_limited_local_draft',identity_match='Three Odia poem bylines securely belong to local ID 81. External interview identifies an Odia writer of this name, but empty captured biography and absence of matching poem text leave the external identity bridge pending.',poems_read=[dict(id=538,title='ଚିରସାଥୀ',basis='Full text read: unshared sorrow, wound/heartbeat, hard arithmetic, winding river and endurance.'),dict(id=456,title='ଧୂଆଁ',basis='Full text read: smoke as burnt trust, lava tears, frozen relationship, history and stone.'),dict(id=95,title='କରୋନା ଭଲ ଥିଲା',basis='Full text read: ironic pandemic refrain, remote Rakhi, Dashahara expense, Diwali smoke and household budget.')],limitations=['Odisha Sambad interview is a strong candidate for biography but no beyond-name link to local contributions established. Interview books and life history kept out of reader draft pending confirmation.','No family health fact inferred from poem 95; its refrain is interpreted as irony, not literal pandemic endorsement.','No new book links until identity match confirmed.'],research_leads=[dict(url='https://odishasambad.in/literature-interview-with-lipsa-patel/',access='opened_page',accessed_on='2026-10-01',finding='3 October 2021 interview by Supriya Panda: Odia fiction/poetry, childhood reading, named books and English story translations; candidate only until local identity bridge is verified.'),dict(url='https://www.aahwaan.com/mags/may20.pdf',access='search_index_excerpt',finding='Same-name Odia fiction byline; no exact local-poem match.'),dict(query='ଲିପସା ପଟେଲ ଧୂଆଁ; ଲିପ୍ସା ପଟେଲ ଚିରସାଥୀ; ଲିପସା କରୋନା ଭଲ ଥିଲା',finding='No reliable exact-text match returned.')],next_action='Author/editor confirm that local contributor is the interviewed Odia writer; then add supported biography and selected books.'))
